Method.Source:
protected void new()
{
    if (!AVACreateContainerIDisposable::current())
    {
        instance = this;
    }
    else
    {
        instance = AVACreateContainerIDisposable::current();
    }
}

/// <summary>
/// AVA_8065_10657_MDEAutoPackContainerType
/// </summary>
/// <returns>
/// Current instance of <c>AVACreateContainerIDisposable</c>
/// </returns>
/// <remarks>
/// AVA_8065_10657_MDEAutoPackContainerType
/// </remarks>
public static AVACreateContainerIDisposable current()
{
    return instance;
}

public static AVACreateContainerIDisposable construct()
{
    return new AVACreateContainerIDisposable();
}
